 await page.getByRole('button',{name:'Configurações',exact:true}).click();await page.getByRole('combobox',{name:'Tema',exact:true}).selectOption('auto');await page.getByRole('button',{name:'Adicionar diretório'}).click();await page.getByRole('button',{name:'D:/Projetos',exact:true}).click();check((await page.getByRole('textbox').inputValue()).includes('D:/Projetos'),'Adicionar diretório');await page.getByRole('button',{name:'Remover diretório D:/Projetos',exact:true}).click();await page.getByRole('textbox').fill('');await page.getByRole('button',{name:'Salvar Alterações'}).click();check(await page.getByRole('dialog',{name:'Revise as preferências'}).count()===1,'Lista vazia permitida');await page.getByRole('button',{name:'OK, Fechar'}).click();await page.getByRole('button',{name:'Restaurar Padrões'}).click();await page.getByRole('combobox',{name:'Tema',exact:true}).selectOption('auto');await page.getByRole('button',{name:'Salvar Alterações'}).click();await page.getByRole('button',{name:'OK, Fechar'}).click();await page.emulateMedia({colorScheme:'light'});await page.waitForFunction(()=>!document.documentElement.classList.contains('dark')); check(!await page.locator('html').evaluate(e=>e.classList.contains('dark')),'Auto claro');await page.emulateMedia({colorScheme:'dark'});await page.waitForFunction(()=>document.documentElement.classList.contains('dark')); check(await page.locator('html').evaluate(e=>e.classList.contains('dark')),'Auto escuro');await page.getByRole('combobox',{name:'Cenário da pasta de logs'}).selectOption('missing');await page.getByRole('button',{name:'Abrir pasta de logs'}).click();check(await page.getByRole('dialog',{name:'Caminho indisponível'}).count()===1,'Logs inexistentes');await page.getByRole('button',{name:'OK, Fechar'}).click();results.push('preferências, diretórios, logs, auto seguindo sistema');
 await page.keyboard.press('Control+h');await page.getByRole('heading',{name:'Histórico de Operações'}).waitFor();await page.getByRole('button',{name:'Carregar exemplos dos tipos de operação'}).click();await page.getByRole('combobox',{name:'Operação',exact:true}).selectOption('Copiar arquivos');check(await page.locator('tbody tr').count()===1,'Tipo operação');await page.getByRole('button',{name:'Limpar filtros',exact:true}).click();await page.getByRole('combobox',{name:'Período',exact:true}).selectOption('today');check((await page.locator('body').innerText()).includes('Total: 1 de 8'),'Hoje');await page.getByRole('button',{name:'Limpar filtros',exact:true}).click();await page.getByRole('combobox',{name:'Cenário do histórico'}).selectOption('clear');await page.getByRole('button',{name:'Limpar',exact:true}).click();await page.getByRole('button',{name:'Confirmar limpeza'}).click();check(await page.getByRole('dialog',{name:'Histórico não foi limpo'}).count()===1,'Falha limpar');await page.getByRole('button',{name:'OK, Fechar'}).click();check(await page.locator('tbody tr').count()===8,'Perda histórico');await page.getByRole('combobox',{name:'Cenário do histórico'}).selectOption('export');await page.getByRole('button',{name:'Exportar',exact:true}).click();check(await page.getByRole('dialog',{name:'Exportação não realizada'}).count()===1,'Falha export');await page.getByRole('button',{name:'OK, Fechar'}).click();results.push('histórico operação/período/total e falhas');
